const hubspotContacts = $input.all();
const results = [];

for (const item of hubspotContacts) {
  const hs = item.json;
  results.push({
    json: {
      email: hs.properties?.email || hs.email,
      first_name: hs.properties?.firstname || hs.firstname,
      last_name: hs.properties?.lastname || hs.lastname,
      company: hs.properties?.company || hs.company,
      phone: hs.properties?.phone || hs.phone,
      job_title: hs.properties?.jobtitle || hs.jobtitle,
      external_id: hs.id,
      source: 'hubspot',
      lead_status: mapHubspotStage(hs.properties?.lifecyclestage)
    }
  });
}

function mapHubspotStage(stage) {
  const mapping = {
    'subscriber': 'new',
    'lead': 'new',
    'marketingqualifiedlead': 'contacted',
    'salesqualifiedlead': 'qualified',
    'opportunity': 'opportunity',
    'customer': 'customer',
    'evangelist': 'customer'
  };
  return mapping[stage] || 'new';
}

return results;

const localContacts = $input.all();
const results = [];

for (const item of localContacts) {
  const contact = item.json;
  results.push({
    json: {
      email: contact.email,
      properties: {
        firstname: contact.first_name,
        lastname: contact.last_name,
        company: contact.company,
        lifecyclestage: mapToHubspotStage(contact.lead_status)
      },
      hubspot_id: contact.external_id
    }
  });
}

function mapToHubspotStage(status) {
  const mapping = {
    'new': 'lead',
    'contacted': 'marketingqualifiedlead',
    'qualified': 'salesqualifiedlead',
    'opportunity': 'opportunity',
    'customer': 'customer',
    'lost': 'other'
  };
  return mapping[status] || 'lead';
}

return results;
